"use strict";(self["webpackChunkJorgeMopanc"]=self["webpackChunkJorgeMopanc"]||[]).push([[976],{5976:function(e){e.exports=JSON.parse('{"projects":[{"id":"depguard","category":"open-source","isPublic":true,"featured":true,"caseStudySlug":"depguard-mcp-security-server","projectType":"Open Source - MCP Security Server","status":"Active Development","title":"depguard","description":"Open-source MCP server for npm dependency security, built in TypeScript with zero runtime dependencies. 12 tools: pre-install guardian, AI hallucination guard, static code analysis with malware pattern detection, dead dependency sweep, dual-source vulnerability audit (npm + GitHub Advisory), AI code review, CycloneDX 1.6 SBOM with VEX. 298 offline tests. Published on npm: npmjs.com/package/depguard-cli.","images":[{"src":"depguard/home.png","alt":"depguard landing page showing MCP Security Server for AI Coding Agents","title":"Landing Page"},{"src":"depguard/demo.png","alt":"depguard live demo showing package audit results in terminal","title":"Live Demo"},{"src":"depguard/description.png","alt":"depguard feature overview with 9 MCP tools and scoring model","title":"Features Overview"},{"src":"depguard/npm.png","alt":"depguard-cli package page on npm registry","title":"npm Package"}],"technologies":[{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"npm","icon":"npmjs-icon.svg"},{"name":"GitHub","icon":"github-icon.svg"}],"links":{"repository":"https://github.com/mopanc/depguard","website":"https://depguard.dev"},"metrics":[{"value":"12","label":"MCP Tools"},{"value":"0","label":"Dependencies"},{"value":"298","label":"Tests"}]},{"id":"gov-analytics-portugal","category":"personal","isPublic":true,"featured":true,"projectType":"Civic Data Platform","status":"Stable","title":"GOV.analytics","description":"Public procurement analytics for Portugal, built on open data from BASE/IMPIC (dados.gov.pt). Turborepo monorepo: Fastify + TypeScript backend with Kysely as type-safe query builder, PostgreSQL with year-based table partitioning and materialized views for fast aggregations, Redis + BullMQ queues, Next.js 15 (App Router) frontend with Tailwind v4. The ETL pipeline ingests over 200k public contracts spanning 2018 to 2026 from XLSX exports: automatic download, parsing, transformation, batch loading with deduplication, view refresh. The frontend exposes contracts, suppliers and analytics: spending summaries, top suppliers, contract drill-downs, search. The \'live\' ambition is constrained by archaic government data formats (Excel-only, year-delayed releases). Historical analysis works on real production data.","images":[{"src":"gov/dashboard.png","alt":"GOV.analytics main dashboard with public spending summary across years and ministries","title":"Dashboard"},{"src":"gov/contratos.png","alt":"Public contracts listing with advanced filters by year, supplier, and entity","title":"Contracts"},{"src":"gov/receitas.png","alt":"Public revenue tracking and breakdowns alongside spending data","title":"Revenues"},{"src":"gov/fontes.png","alt":"Open data sources and ingestion status from BASE/IMPIC and dados.gov.pt","title":"Data Sources"},{"src":"gov/analytics.png","alt":"Analytics overview with year-over-year spending trends and totals","title":"Analytics"},{"src":"gov/analytics-1.png","alt":"Analytics drill-down with detailed views by ministry, region or category","title":"Analytics Drill-down"},{"src":"gov/analytics-2.png","alt":"Analytics deep-dive with comparative charts and supplier rankings","title":"Analytics Deep-dive"},{"src":"gov/search.png","alt":"Advanced search with multi-field filters across contracts, suppliers and entities","title":"Search"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"Fastify","icon":""},{"name":"Kysely","icon":""},{"name":"PostgreSQL","icon":""},{"name":"Redis","icon":""},{"name":"BullMQ","icon":""},{"name":"Next.js 15","icon":""},{"name":"Tailwind CSS","icon":"tailwindcss-icon.svg"},{"name":"Turborepo","icon":""}],"links":{"repository":null,"website":null},"metrics":[{"value":"200k+","label":"Contracts"},{"value":"9","label":"Year Span"},{"value":"6","label":"SQL Migrations"}]},{"id":"workora-recruitment-saas","category":"personal","isPublic":true,"featured":true,"projectType":"AI-Powered Recruitment SaaS","status":"In Development","title":"Workora","description":"Recruitment SaaS connecting companies with candidates. Backend in Node.js/Express 5 with TypeScript, Prisma ORM and PostgreSQL (31 controllers, 30+ services, 28 route files). React 18/TypeScript frontend with Vite, Tailwind and shadcn/ui (18 pages, 21 component groups). Companies post credit-gated jobs and review applicants. Candidates upload CVs, search and apply with one click. Gemini AI scores candidate-job fit and surfaces recommendations; humans make the final call. Stripe for credits and subscriptions, LinkedIn OAuth for one-tap login plus profile import, Socket.IO for real-time notifications, Bull queue with SMTP/SendGrid/Mailgun for email pipelines, PDFKit for invoices and reports, full PT/EN i18n. Role-based access for Admin, Company and Candidate.","images":[{"src":"workora/home.png","alt":"Workora landing page presenting the AI-powered recruitment platform","title":"Landing"},{"src":"workora/jobs-listing.png","alt":"Public job listings with search, filters and one-click apply","title":"Jobs Listing"},{"src":"workora/candidate-profile.png","alt":"Candidate profile with parsed CV, skills and applications history","title":"Candidate Profile"},{"src":"workora/interview.png","alt":"Interview management with scheduling and candidate-company communication","title":"Interview Management"},{"src":"workora/company-dashboard.png","alt":"Company dashboard with applicant tracking, analytics and job management","title":"Company Dashboard"},{"src":"workora/ai-matching.png","alt":"Gemini AI candidate matching with fit scores and ranked recommendations","title":"AI Matching"},{"src":"workora/analytics.png","alt":"Recruitment analytics with hiring funnel, conversion metrics and platform insights","title":"Analytics & Insights"},{"src":"workora/social-media.png","alt":"Social media integration for sharing job postings and amplifying reach","title":"Social Media Sharing"},{"src":"workora/pricing-credits.png","alt":"Credit purchase and subscription page with Stripe payment integration","title":"Credits & Pricing"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express","icon":"express-js.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"Prisma","icon":""},{"name":"PostgreSQL","icon":""},{"name":"Tailwind CSS","icon":"tailwindcss-icon.svg"},{"name":"Vite","icon":""},{"name":"Stripe","icon":""},{"name":"Gemini AI","icon":""},{"name":"Redis","icon":""},{"name":"Socket.IO","icon":"socketio.svg"}],"links":{"repository":null,"website":null},"metrics":[{"value":"31","label":"Controllers"},{"value":"30+","label":"Services"},{"value":"18","label":"Pages"}]},{"id":"cyborg-ai-platform","category":"personal","isPublic":true,"featured":true,"projectType":"Multi-Tenant AI Platform","status":"Active Development","title":"Cyborg","description":"Multi-tenant AI platform for managing industrial and IoT equipment through chat. Three services: a Go backend with 19 modules running on PostgreSQL and Redis, a Python FastAPI engine on Qdrant that talks to Claude, OpenAI or local Ollama, and a React/TypeScript frontend (Vite, Tailwind, shadcn/ui). Drop in PDFs, DOCX, Excel, Markdown or HTML, and each agent gets its own knowledge base. Agents make real HTTP calls with Basic, Bearer or OAuth2 auth, and talk to equipment over Modbus, MQTT or OPC-UA. Role-based multi-tenant access, AI-generated alerts pulled from equipment data, conversation analytics, license gating per feature. Ships with a device emulator for end-to-end testing without real hardware.","images":[{"src":"cyborg/home.png","alt":"Cyborg platform home with agents, equipment overview and tenant context","title":"Platform Home"},{"src":"cyborg/dashboard.png","alt":"Dashboard with usage analytics, conversation metrics and tenant overview","title":"Dashboard Overview"},{"src":"cyborg/equipment.png","alt":"Equipment management screen with device registration and protocol configuration","title":"Equipment Management"},{"src":"cyborg/rag-ingest.png","alt":"RAG document ingestion uploading PDF, DOCX, Excel, Markdown and HTML files into per-agent knowledge bases","title":"RAG Document Ingestion"},{"src":"cyborg/agent-config.png","alt":"Agent configuration with system prompt, tool actions and knowledge base assignment","title":"Agent Configuration"},{"src":"cyborg/chat.png","alt":"AI agent chat with streaming responses and contextual answers","title":"Agent Chat"},{"src":"cyborg/chat-1.png","alt":"Agent chat executing tool-calling actions on real devices over HTTP/Modbus/MQTT/OPC-UA","title":"Chat with Tool-Calling"}],"technologies":[{"name":"Go","icon":""},{"name":"Python","icon":"python-icon.svg"},{"name":"FastAPI","icon":""},{"name":"React","icon":"reactjs-icon.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"PostgreSQL","icon":""},{"name":"Qdrant","icon":""},{"name":"Redis","icon":""},{"name":"Docker","icon":"docker-icon.svg"},{"name":"Tailwind CSS","icon":"tailwindcss-icon.svg"},{"name":"Anthropic SDK","icon":""},{"name":"OpenAI SDK","icon":""},{"name":"Ollama","icon":""}],"links":{"repository":null,"website":null},"metrics":[{"value":"3","label":"Service Architecture"},{"value":"4","label":"Device Protocols"},{"value":"5","label":"Doc Formats"}]},{"id":"montedge-personal-finance","category":"personal","isPublic":true,"featured":false,"projectType":"Personal Finance Platform","status":"Personal use","title":"MontEdge","description":"Personal finance platform that tracks every account, asset and movement in one place. Rails API on MySQL, Next.js + TypeScript frontend with protected routes. The domain covers 20+ entities: bank accounts, wallets, brokers and investment assets with dividend tracking, credit cards (charges, installment plans, payments), revenues, expenses with split logic and store-level price comparison, transfers, liabilities, VAT rates. Analytics on top: currency conversion, cheapest-price detection per article, dividend yield breakdowns. Built jointly with my brother (Rails dev). I use it daily for my own finances.","images":[{"src":"montedge/dashboard.png","alt":"MontEdge dashboard overview showing financial summary across accounts, investments and recent movements","title":"Dashboard"},{"src":"montedge/accounts.png","alt":"Bank accounts and wallets list with balances and currency","title":"Accounts & Wallets"},{"src":"montedge/investments.png","alt":"Investment assets, brokers and dividend tracking","title":"Investments & Dividends"},{"src":"montedge/credit-cards.png","alt":"Credit card management with charges, installment plans and payments","title":"Credit Cards"},{"src":"montedge/analytics.png","alt":"Analytics with currency conversion and dividend yield breakdowns","title":"Analytics"}],"technologies":[{"name":"Ruby on Rails","icon":""},{"name":"MySQL","icon":"mysql-official.svg"},{"name":"Next.js","icon":""},{"name":"React","icon":"reactjs-icon.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"Tailwind CSS","icon":"tailwindcss-icon.svg"},{"name":"Docker","icon":"docker-icon.svg"}],"links":{"repository":null,"website":null}},{"id":"multi-location-enterprise-sync","category":"professional","isPublic":false,"featured":true,"caseStudySlug":"federated-pos-synchronization","projectType":"Enterprise Software - Business Management Platform","status":"In Production","title":"Multi-Location Enterprise Sync","description":"Multi-store management platform deployed across one organization\'s locations. Node.js, Express.js, TypeScript, TypeORM and SQL Server on the backend, React + TypeScript on the frontend, Socket.IO for real-time. Covers store management, sales analytics with statistical dashboards, inventory control, user management with granular permissions, and process automation. Key bits: remote device configuration via a proprietary ETPROXY protocol, business data sync across locations, comparative analysis, product rankings, PDF/CSV export, rule-based price management, automated backups, and device-bound licensing.","images":[{"src":"qore/home.png","alt":"Multi-Location Enterprise Sync — illustrative dashboard view (AI-generated visualization, not the actual proprietary UI)","title":"Platform Overview"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express.js","icon":"express-js.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"TypeORM","icon":"Typeorm--Streamline-Simple-Icons.svg"},{"name":"SQL Server","icon":"microsoft-sql-server.svg"},{"name":"Socket.IO","icon":"socketio.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"RESTful API","icon":"getpostman-icon.svg"},{"name":"C#","icon":"visualstudio_code-icon.svg"},{"name":"InnoSetup","icon":"innosetup.svg"}],"links":{"repository":null},"metrics":[{"value":"72%","label":"Memory Cut"},{"value":"96%","label":"Faster Pipeline"},{"value":"500k+","label":"Docs/Month"}]},{"id":"qscope-v3-trading-platform","category":"personal","isPublic":true,"featured":true,"projectType":"Autonomous Crypto Trading Platform","status":"Live Testing","title":"Q-Scope V3","description":"Autonomous crypto trading platform with AI decision-making, a 7-analyst panel, and a learning engine that adjusts over time. Polyglot architecture: NestJS + TypeScript backend (11 modules, 19 services, 56 files), a Python FastAPI analyst micro-service running 7 analysts (RSI, MACD, Trend, Volume, Elliott Wave, Fibonacci, Hurst) and extracting over 100 features, Socket.IO gateway for live cycle telemetry, PostgreSQL for trades, decisions and learning data, Redis for price cache and pub/sub, Ollama for local LLM agents (decision plus post-trade learning review). The Analysis Cycle runs SCAN → SYNC → ANALYZE → CONSENSUS → AI DECIDE → EXECUTE → MONITOR → EXIT → LEARN. Analyst weights adapt over time, tuned by historical accuracy per market regime. Live integration with Binance Futures (real signed orders), CryptoCompare/CoinGecko news with sentiment classification, Fear & Greed Index. Versioned prompt system (CRUD + revert) so AI behavior can be governed without redeploys.","images":[{"src":"qscope-v3/dashboard.png","alt":"Q-Scope V3 dashboard with live cycle telemetry and the 7-analyst panel","title":"Dashboard"},{"src":"qscope-v3/decisions.png","alt":"AI decision engine output: 7-analyst consensus with confidence scores per signal","title":"AI Decisions"},{"src":"qscope-v3/analytics.png","alt":"Performance analytics across trades, decisions and learning data over time","title":"Analytics"},{"src":"qscope-v3/position.png","alt":"Active position monitoring with stop-loss and take-profit levels","title":"Active Position"},{"src":"qscope-v3/position-1.png","alt":"Position detail view with entry, exits and analyst contribution breakdown","title":"Position Detail"},{"src":"qscope-v3/history.png","alt":"Trade history with per-trade post-mortem and learning review","title":"Trade History"},{"src":"qscope-v3/news.png","alt":"Market news feed with sentiment classification and Fear & Greed Index","title":"News & Sentiment"}],"technologies":[{"name":"NestJS","icon":""},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"Python","icon":"python-icon.svg"},{"name":"FastAPI","icon":""},{"name":"React","icon":"reactjs-icon.svg"},{"name":"Socket.IO","icon":"socketio.svg"},{"name":"PostgreSQL","icon":""},{"name":"Redis","icon":""},{"name":"Ollama","icon":""},{"name":"Binance API","icon":""}],"links":{"repository":null,"website":null},"metrics":[{"value":"7","label":"Analyst Panel"},{"value":"9-Phase","label":"Cycle"},{"value":"Adaptive","label":"Weights"}]},{"id":"dataconvert-saas-platform","category":"personal","isPublic":true,"featured":true,"caseStudySlug":"dataconvert-template-processing","projectType":"SaaS Data Processing Platform","status":"In Development","title":"DataConvert","description":"SaaS platform for automating corporate data processing. Multi-tenant, with custom templates, PDF table extraction via tabula-py and pdfplumber, visual column mapping, and automated PDF→CSV/JSON conversion. Stack: Node.js/TypeScript/Express backend, React/TypeScript frontend, JWT auth, plan tiers (Free/Personal/Enterprise), and a Python FastAPI service for PDF processing. Analytics dashboard, template management, drag-and-drop upload, and a multi-tenancy system for enterprises.","images":[{"src":"data-convert/landing_page.jpg","alt":"Registration with plan selection and multi-tenancy","title":"User Registration"},{"src":"data-convert/dashboard.jpg","alt":"Main dashboard with statistics and recent templates","title":"Analytics Dashboard"},{"src":"data-convert/my_templates.jpg","alt":"Template management with filters and advanced search","title":"Template Management"},{"src":"data-convert/import.jpg","alt":"Upload interface with drag-and-drop and batch processing","title":"File Import System"},{"src":"data-convert/subscriptions.jpg","alt":"Authentication interface with JWT system","title":"Authentication System"}],"technologies":[{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express.js","icon":"express.svg"},{"name":"TypeORM","icon":"nodejs-icon.svg"},{"name":"PostgreSQL","icon":"mysql-official.svg"},{"name":"Python","icon":"python-icon.svg"},{"name":"FastAPI","icon":"python-icon.svg"},{"name":"Vite","icon":"js.svg"},{"name":"TailwindCSS","icon":"tailwindcss-icon.svg"},{"name":"Tabula-py","icon":"python-icon.svg"},{"name":"PDFplumber","icon":"python-icon.svg"},{"name":"Pandas","icon":"python-icon.svg"},{"name":"JWT Authentication","icon":"getpostman-icon.svg"},{"name":"Bcrypt","icon":"visualstudio_code-icon.svg"},{"name":"Axios","icon":"js.svg"},{"name":"Multer","icon":"nodejs-icon.svg"}],"links":{"repository":"https://github.com/mopanc/dataconvert-platform","website":null},"metrics":[{"value":"2","label":"AI Extractors"},{"value":"SaaS","label":"Multi-tenant"},{"value":"3","label":"Plan Tiers"}]},{"id":"payment-machine-backend","category":"professional","isPublic":false,"featured":true,"projectType":"Embedded Systems - Payment Machine Backend","status":"In Production","title":"Payment Machine Backend","description":"Embedded backend for an automated payment machine, written in pure C to drive the hardware: hoppers, coin and bill validators, recycler, security safe. CCTalk and ID003 for peripherals, MQTT for the mobile companion app. Tight memory management in a constrained embedded environment, leak prevention, binary protocol handling, real-time sync. Automatic value validation, change calculation, LED control, remote MQTT monitoring, detailed transaction logging.","images":[{"src":"alice4cash/alice.png","alt":"Payment machine backend — illustrative hardware visualization (AI-generated, not the actual proprietary product)","title":"Payment Machine"}],"technologies":[{"name":"C Programming","icon":"c-programming.svg"},{"name":"MQTT Protocol","icon":"mqtt-icon-solid.svg"},{"name":"CCTalk Protocol","icon":"binary-svgrepo-com.svg"},{"name":"ID003 Protocol","icon":"binary-svgrepo-com.svg"},{"name":"Embedded Systems","icon":"memory.svg"},{"name":"Linux Embedded","icon":"linux.svg"},{"name":"IoT Communication","icon":"iot.svg"}],"links":{"repository":null},"metrics":[{"value":"0","label":"Memory Leaks"},{"value":"3+","label":"HW Protocols"},{"value":"Live","label":"MQTT Feed"}]},{"id":"truck-scale-automation-platform","category":"professional","isPublic":false,"featured":true,"projectType":"Industrial Self-Service Weighbridge System","status":"In Production · Multi-site","title":"Industrial Truck Scale Automation Platform","description":"On-premise truck scale automation deployed across multiple industrial sites. Replaces manual weighing with self-service driver flows. The on-premise executable orchestrates the weighbridge end-to-end: scale instruments, programmable I/O boards (barriers, traffic lights, sensors), MUPI LED displays at both scale entries that guide drivers through every step, ticket printers, RFID readers, IP cameras with automatic license-plate recognition (ANPR), MJPEG and RTSP streams (custom integration via go2rtc). Companion Raspberry Pi monitors run the trucker and check-in interfaces, so a full weighbridge operates without anyone on site. Desktop app for local printer control and remote operation, plus a CMS for managing weighing documents and operator workflows. Built in Node.js with SQL Server, packaged via pkg + InnoSetup, hardened with Watchdog process supervision. Angular frontend.","images":[{"src":"truck-scale/dashboard.png","alt":"Truck scale automation platform — illustrative weighbridge dashboard view (AI-generated visualization, not the actual proprietary UI)","title":"Weighbridge Operation"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"JavaScript","icon":"javascript.svg"},{"name":"SQL Server","icon":"microsoft-sql-server.svg"},{"name":"Angular","icon":""},{"name":"go2rtc","icon":""},{"name":"RTSP","icon":""},{"name":"MJPEG","icon":""},{"name":"InnoSetup","icon":"innosetup.svg"},{"name":"pkg","icon":""},{"name":"Watchdog","icon":""}],"links":{"repository":null,"website":null},"metrics":[{"value":"Multi-site","label":"Production"},{"value":"Zero","label":"Operators on Site"},{"value":"8","label":"Hardware Integrations"}]}]}')}}]);